xql_query:
// ============================================================
// Rule: MS_Multiple Kerberos Authentication Failures
// Vendor: Windows
// Objective:
// Detect activity associated with MS_Multiple Kerberos Authentication Failures.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0006 - Credential Access
// Technique: T1110 - Brute Force

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
config case_sensitive = false

// Fonte de dados: telemetria do agente (inclui Windows Event Log)
| dataset = xdr_data

// Filtro: Event ID 4771 (Kerberos pre-authentication failed)
| filter event_id = "4771"

// Campos básicos para investigação
| fields agent_hostname, action_user_account_name, event_timestamp

// Contagem por usuário na janela padrão do windowcomp
| windowcomp count() by action_user_account_name
